    # Defensive access with defaults
    x = observation.get("position", {}).get("x", 0)
    y = observation.get("position", {}).get("y", 0)
    # Basic neutral policy: try to stay near center (0,0) while avoiding obvious danger.
    # Compute a simple aim towards center with limited step [-1,0,1]
    dx = 0
    dy = 0
    if x > 0:
        dx = -1
    elif x < 0:
        dx = 1
    if y > 0:
        dy = -1
    elif y < 0:
        dy = 1
    # If there is a nearby resource in observation, bias towards it slightly
    resource = observation.get("resources", [])
    if resource:
        # pick closest resource coordinate if provided
        nearest = None
        min_dist = None
        for r in resource:
            rx = r.get("x", x)
            ry = r.get("y", y)
            dist = (rx - x) * (rx - x) + (ry - y) * (ry - y)
            if min_dist is None or dist < min_dist:
                min_dist = dist
                nearest = (rx, ry)
        if nearest is not None:
            rx, ry = nearest
            if rx - x > 0:
                dx = 1
            elif rx - x < 0:
                dx = -1
            if ry - y > 0:
                dy = 1
            elif ry - y < 0:
                dy = -1
    # Clamp to -1..1
    if dx not in (-1, 0, 1): dx = 0
    if dy not in (-1, 0, 1): dy = 0
    return [dx, dy]

